<?php
require __DIR__.'/../src/bootstrap.php';require_admin();require __DIR__.'/../src/RouteBoxClient.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$a=$_POST['action']??'';try{
if($a==='add_server'){$n=trim($_POST['name']??'');$url=rtrim(trim($_POST['url']??''),'/');$u=trim($_POST['username']??'');$p=$_POST['password']??'';if(!$n||!filter_var($url,FILTER_VALIDATE_URL)||!$u||!$p)throw new RuntimeException('اطلاعات ناقص است');db()->prepare('INSERT INTO routebox_servers(name,base_url,user_enc,pass_enc,verify_tls,enabled,created_at)VALUES(?,?,?,?,?,?,?)')->execute([$n,$url,enc($u),enc($p),isset($_POST['verify_tls'])?1:0,1,time()]);log_event('info','RouteBox server added '.$n);}
elseif($a==='test_server'){$q=db()->prepare('SELECT * FROM routebox_servers WHERE id=?');$q->execute([(int)$_POST['id']]);$s=$q->fetch(PDO::FETCH_ASSOC);if(!$s)throw new RuntimeException('سرور پیدا نشد');$c=new RouteBoxClient($s['base_url'],dec($s['user_enc']),dec($s['pass_enc']),(bool)$s['verify_tls']);$_SESSION['flash']='اتصال موفق: '.json_encode($c->status(),JSON_UNESCAPED_UNICODE);}
elseif($a==='toggle_server'){db()->prepare('UPDATE routebox_servers SET enabled=1-enabled WHERE id=?')->execute([(int)$_POST['id']]);}
elseif($a==='save_settings'){$v=max(1,min(720,(int)$_POST['trial_hours']));db()->prepare("INSERT INTO settings(key,value)VALUES('trial_hours',?)ON CONFLICT(key)DO UPDATE SET value=excluded.value")->execute([$v]);if(trim($_POST['telegram_token']??''))db()->prepare("INSERT INTO settings(key,value)VALUES('telegram_token',?)ON CONFLICT(key)DO UPDATE SET value=excluded.value")->execute([enc(trim($_POST['telegram_token']))]);}
}catch(Throwable $e){$_SESSION['flash']='خطا: '.$e->getMessage();}header('Location:/');exit;}
$servers=db()->query('SELECT * FROM routebox_servers ORDER BY id')->fetchAll(PDO::FETCH_ASSOC);$users=db()->query('SELECT * FROM telegram_users ORDER BY last_seen DESC LIMIT 50')->fetchAll(PDO::FETCH_ASSOC);$trial=(int)(db()->query("SELECT value FROM settings WHERE key='trial_hours'")->fetchColumn()?:12);$hasToken=(bool)db()->query("SELECT value FROM settings WHERE key='telegram_token'")->fetchColumn();$flash=$_SESSION['flash']??'';unset($_SESSION['flash']);
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RouteBox Telegram Bot</title><style>body{margin:0;background:#0b1120;color:#e5e7eb;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif}.wrap{max-width:1050px;margin:auto;padding:25px}.card{background:#111827;border:1px solid #293548;border-radius:18px;padding:20px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}input{box-sizing:border-box;width:100%;padding:10px;margin:6px 0 12px;border-radius:9px;border:1px solid #374151;background:#0f172a;color:white}button{background:#2563eb;color:white;border:0;border-radius:9px;padding:9px 13px}.row{display:flex;gap:12px;justify-content:space-between;align-items:center;border-top:1px solid #243044;padding:12px 0}.muted{color:#94a3b8;font-size:13px}.flash{background:#172554;padding:12px;border-radius:10px}.badge{background:#f59e0b;color:#111;padding:4px 9px;border-radius:20px;font-size:11px}.ok{color:#34d399}.off{color:#fb7185}a{color:#93c5fd}</style></head><body><div class="wrap"><h1>🚀 RouteBox Telegram Bot <span class="badge">BETA</span></h1><p><a href="/logout.php">خروج</a></p><?php if($flash):?><div class="flash"><?=h($flash)?></div><?php endif;?><div class="card"><h2>⚙️ تنظیمات ربات</h2><form method="post"><input type="hidden" name="action" value="save_settings"><label>Telegram Bot Token</label><input name="telegram_token" type="password" placeholder="<?= $hasToken?'Token already configured':'123456:ABC...' ?>"><label>مدت تست (ساعت)</label><input type="number" name="trial_hours" min="1" max="720" value="<?=h((string)$trial)?>"><button>💾 ذخیره تنظیمات</button></form><p class="muted">Token در SQLite با رمزنگاری SecretBox ذخیره می‌شود.</p></div><div class="card"><h2>🌐 سرورهای RouteBox</h2><form method="post"><input type="hidden" name="action" value="add_server"><div class="grid"><div>نام<input name="name" placeholder="Turkey #1" required></div><div>URL<input name="url" placeholder="https://1.2.3.4:8080" required></div><div>Username<input name="username" required></div><div>Password<input type="password" name="password" required></div></div><label><input type="checkbox" name="verify_tls" checked style="width:auto"> بررسی TLS</label><br><button>➕ افزودن</button></form><?php foreach($servers as $s):?><div class="row"><div><b><?=h($s['name'])?></b><div class="muted"><?=h($s['base_url'])?></div></div><div class="<?= $s['enabled']?'ok':'off'?>"><?= $s['enabled']?'● فعال':'● غیرفعال'?></div><div><form method="post" style="display:inline"><input type="hidden" name="action" value="test_server"><input type="hidden" name="id" value="<?=$s['id']?>"><button>🧪</button></form><form method="post" style="display:inline"><input type="hidden" name="action" value="toggle_server"><input type="hidden" name="id" value="<?=$s['id']?>"><button>⏯️</button></form></div></div><?php endforeach;?></div><div class="card"><h2>👥 کاربران Telegram</h2><?php foreach($users as $u):?><div class="row"><span><?=h($u['first_name']?:$u['username']?:$u['telegram_id'])?></span><span class="muted">@<?=h($u['username']?:'—')?> · <?=date('Y-m-d H:i',$u['last_seen'])?></span></div><?php endforeach;if(!$users):?><p class="muted">هنوز کاربری وجود ندارد.</p><?php endif;?></div></div></body></html>
